					if err := updateStrategyOptions(ctx, cmd.OutOrStdout(), opts); err != nil {
						return err
					}
				}
				if hasSummaryProviderFlags(cmd) {
					if err := updateSummaryGenerationSettings(ctx, cmd.OutOrStdout(), summarizeProvider, summarizeModel, opts); err != nil {
						return err
					}
				}
				return nil
